options {
  server = server;
  exit = 288;
}

contract NFTMint(
    bytes32 collectionCtrlIdTxid,
    int collectionCtrlIdGidx,
    pubkey issuerPk
) {
    function mint(bytes32 nftAssetIdTxid, int nftAssetIdGidx, pubkey recipientPk, signature issuerSig) {
        let nftGroup = tx.assetGroups.find(nftAssetIdTxid, nftAssetIdGidx);

        require(nftGroup.isFresh == 1, "must be fresh");

        require(nftGroup.delta == 1, "must mint exactly 1");

        require(nftGroup.controlIs(collectionCtrlIdTxid, collectionCtrlIdGidx), "wrong collection");

        let ctrlGroup = tx.assetGroups.find(collectionCtrlIdTxid, collectionCtrlIdGidx);
        require(ctrlGroup.delta == 0, "control must be retained");

        require(tx.outputs[0].assets.lookup(nftAssetIdTxid, nftAssetIdGidx) == 1, "NFT not in output");
        require(tx.outputs[0].scriptPubKey == new SingleSig(recipientPk), "wrong recipient");

        require(checkSig(issuerSig, issuerPk), "bad issuer sig");
    }

    function transfer(bytes32 nftAssetIdTxid, int nftAssetIdGidx, pubkey newOwnerPk, signature ownerSig, pubkey ownerPk) {
        let nftGroup = tx.assetGroups.find(nftAssetIdTxid, nftAssetIdGidx);

        require(nftGroup.isFresh == 0, "cannot be fresh");

        require(nftGroup.delta == 0, "must be transfer");

        require(nftGroup.controlIs(collectionCtrlIdTxid, collectionCtrlIdGidx), "wrong collection");

        require(tx.outputs[0].assets.lookup(nftAssetIdTxid, nftAssetIdGidx) == 1, "NFT not in output");
        require(tx.outputs[0].scriptPubKey == new SingleSig(newOwnerPk), "wrong dest");

        require(checkSig(ownerSig, ownerPk), "bad owner sig");
    }

    function burn(bytes32 nftAssetIdTxid, int nftAssetIdGidx, signature ownerSig, pubkey ownerPk) {
        let nftGroup = tx.assetGroups.find(nftAssetIdTxid, nftAssetIdGidx);

        require(nftGroup.isFresh == 0, "cannot burn fresh asset");

        require(nftGroup.sumInputs >= nftGroup.sumOutputs + 1, "must burn exactly 1");

        require(checkSig(ownerSig, ownerPk), "bad owner sig");
    }
}
